/**
 * Ambil foto langsung dari kamera perangkat.
 *
 * Latar belakang: WebView Android tidak punya action sheet bawaan seperti
 * WKWebView di iOS, jadi `<input type="file">` biasa selalu jatuh ke document
 * picker. Capacitor baru membuka ACTION_IMAGE_CAPTURE bila daftar `accept`
 * memuat token literal `image/*` DAN atribut `capture` ada
 * (BridgeWebChromeClient.onShowFileChooser). Input attachment kita menerima PDF
 * juga, sehingga syarat itu tidak pernah terpenuhi — karenanya kamera dipicu
 * lewat input terpisah di sini, bukan dengan mengubah input utama.
 *
 * Di iOS, `capture` membuka kamera langsung (melewati action sheet). Ini butuh
 * NSCameraUsageDescription di Info.plist proyek native — tanpa itu iOS
 * menerminasi aplikasi begitu kamera dibuka.
 */
import { isNativeApp } from '../data/mobile'

/**
 * True bila UI perlu menampilkan tombol "Ambil Foto" terpisah.
 * Di browser biasa atribut `capture` diabaikan (hanya membuka file picker
 * lagi), jadi tombolnya cuma relevan di dalam aplikasi.
 */
export function canUseCamera() {
	return isNativeApp()
}

/**
 * Buka kamera dan resolve File hasil jepretan, atau null bila dibatalkan.
 * Inputnya dibuat sementara di DOM supaya tidak perlu markup di tiap halaman.
 */
export function capturePhoto() {
	return new Promise((resolve) => {
		const input = document.createElement('input')
		input.type = 'file'
		input.accept = 'image/*' // wajib token ini agar Capacitor pakai kamera
		input.setAttribute('capture', 'environment') // kamera belakang
		input.style.display = 'none'
		document.body.appendChild(input)

		let settled = false
		const finish = (file) => {
			if (settled) return
			settled = true
			window.removeEventListener('focus', onWindowFocus)
			input.remove()
			resolve(file || null)
		}

		// Tidak semua WebView mengirim event 'cancel'. Saat aplikasi kembali
		// fokus tanpa file terpilih, anggap dibatalkan — beri jeda karena
		// 'change' kadang menyusul sesaat setelah fokus kembali.
		function onWindowFocus() {
			setTimeout(() => {
				if (!input.files || !input.files.length) finish(null)
			}, 1000)
		}

		input.addEventListener('change', () => finish(input.files && input.files[0]), {
			once: true,
		})
		input.addEventListener('cancel', () => finish(null), { once: true })
		window.addEventListener('focus', onWindowFocus)

		input.click()
	})
}
